import { describe, expect, test } from "vitest";
import { cmlIndexSource, importName } from "./cml";

describe("cmlIndexSource", () => {
  test("imports every template and exports them as one array, sorted", () => {
    expect(cmlIndexSource(["../cml/b/Zed.xml", "../cml/a/App.xml"])).toBe(
      [
        "// GENERATED by scripts/web.ts from packages/tg-web/cml — do not edit.",
        'import App from "../cml/a/App.xml";',
        'import Zed from "../cml/b/Zed.xml";',
        "",
        "export default [",
        "  App,",
        "  Zed,",
        "];",
        "",
      ].join("\n"),
    );
  });

  test("a dotted template name becomes an identifier", () => {
    expect(importName("../cml/app/Page.SignIn.xml")).toBe("Page_SignIn");
  });

  /** Two files named alike in different folders would shadow one another. */
  test("refuses two templates that import under one name", () => {
    expect(() => cmlIndexSource(["../cml/a/Page.xml", "../cml/b/Page.xml"])).toThrow(/Page/);
  });
});
